# -*- coding: utf-8 -*-
from taf.ul.ettf.logger import custom_logger
from taf.ul.ettf.msg_capture.condition_wrappers.condition import Condition
from taf.ul.ettf.msg_capture.condition_wrappers.msg_collector import MsgCollector
from taf.ul.ettf.utils.exception import LibraryError
from taf.ul.ettf.utils import exception_causes
import queue


logger = custom_logger('CaptureConditionTracker')


class ConditionNotMet(LibraryError):
    def __init__(self, msg='Captured messages are different than expected'):
        super(ConditionNotMet, self).__init__(
            exception_causes.CONDITION_NOT_MET,
            msg)


class CaptureConditionTracker(object):
    def __init__(self, timer, packet_extractor):
        self._timer = timer
        self._packet_extractor = packet_extractor
        self._mismatches = []
        self._packets = []
        self._is_condition_met = False

    def wait_for_condition(self, queue, condition, timeout):
        if not isinstance(condition, Condition):
            condition = MsgCollector(condition)
        self._packets = []
        self._timer.start(timeout)
        self._is_condition_met = False

        while not self._is_condition_met:
            self._try_receiving_data(condition, queue)
            self._reevaluate_condition(condition)

    @property
    def captured_packets(self):
        return self._packets

    def _try_receiving_data(self, condition, queue_instance):
        try:
            chunk = queue_instance.get(timeout=self._timer.remaining_time)
            self._packet_extractor.data_received(chunk)

        except queue.Empty:
            if not condition.finish():
                raise ConditionNotMet()
            self._is_condition_met = True

    def _reevaluate_condition(self, condition):
        if not self._is_condition_met:
            for packet in self._packet_extractor.extract():
                self._packets.append(packet)

                matching_result = condition.validate(packet)
                self._append_mismatches(matching_result, packet)

                if matching_result:
                    self._is_condition_met = True
                    break

    def _append_mismatches(self, matching_result, packet):
        try:
            if matching_result.mismatches:
                self._mismatches.append((matching_result.mismatches, packet))
        except Exception as e:
            logger.warn('Exception raised while storing mismatches: {}'.format(e))
